def encode_cp437(text: str) -> bytes:
    out = bytearray()
    for char in text:
        if char == "\n":
            out.extend(b"\r\n")
        elif char in GRAPH:
            out.append(GRAPH[char])
        else:
            out.extend(char.encode("cp437"))
    return bytes(out)

def fit(text: str, width: int = WIDTH) -> str:
    if len(text) == width:
        return text
    if len(text) > width:
        return text[:width]
    return text + (" " * (width - len(text)))

def csv_escape(value: object) -> str:
    text = "" if value is None else str(value)
    if any(ch in text for ch in ',\"\n'):
        return '"' + text.replace('"', '""') + '"'
    return text

