describe('application composition seam', () => {
  afterEach(() => {
    vi.resetModules();
    vi.unstubAllGlobals();
  });

  // Full-suite boot imports main + mounts the real shell; under parallel
  // jsdom workers this can exceed the default 5s without hanging.
  it.each([null, 'initial.md'])('boots without native imports and synchronizes the initial document: %s', async (initialPath) => {
    const mainSource = readFileSync(join(root, 'src/main.js'), 'utf8');
    const ingressSource = readFileSync(join(root, 'src/document-ingress-controller.js'), 'utf8');
    expect(mainSource).not.toMatch(/from '@tauri-apps\//);
    expect(ingressSource).not.toMatch(/from '@tauri-apps\//);
    expect(mainSource).not.toMatch(/from '\.\/editor-session\.js'/);
    const adapterSource = readFileSync(join(root, 'src/application-runtime-adapters.js'), 'utf8');
    expect(adapterSource).not.toMatch(/from '\.\/diagram-renderer\.js'/);
    expect(mainSource).toMatch(/export async function startOpenMdApplication/);
    expect(mainSource).toMatch(/createDocumentLinkController/);

    const dom = new JSDOM(html, {
      url: `https://open.md.local/${initialPath ? '?file=initial.md' : ''}`,
      pretendToBeVisual: true,
      runScripts: 'outside-only',
    });
    dom.window.__VITEST__ = true;
    dom.window.__OPENMD_PREVIEW_DOCUMENTS__ = {
      'initial.md': { source: '# Initial document', html: '<h1>Initial document</h1>' },
    };
    dom.window.matchMedia = () => ({
      matches: false,
      addEventListener() {},
      removeEventListener() {},
    });
    dom.window.ResizeObserver = class {
      observe() {}
      unobserve() {}
      disconnect() {}
    };
    vi.stubGlobal('window', dom.window);
    vi.stubGlobal('document', dom.window.document);
    vi.stubGlobal('HTMLElement', dom.window.HTMLElement);
    vi.stubGlobal('Element', dom.window.Element);
    vi.stubGlobal('Node', dom.window.Node);
    vi.stubGlobal('CustomEvent', dom.window.CustomEvent);
    vi.stubGlobal('DOMParser', dom.window.DOMParser);
    vi.stubGlobal('MutationObserver', dom.window.MutationObserver);
    vi.stubGlobal('requestAnimationFrame', (cb) => dom.window.setTimeout(() => cb(0), 0));
    vi.stubGlobal('cancelAnimationFrame', (id) => dom.window.clearTimeout(id));

    const { startOpenMdApplication } = await import('./main.js');
    const app = await startOpenMdApplication();
    expect(app.currentPath()).toBe(initialPath);
    expect(app.zoom()).toBe(1);
    if (initialPath) {
      dom.window.document.getElementById('edit-mode-button').click();
      await vi.waitFor(() => {
        expect(dom.window.document.getElementById('editor-canvas').textContent).toContain('Initial document');
      });
    }
    await app.dispose();
  }, 20_000);
})

describe('Application Lifecycle', () => {
  it('owns resources and listeners where they are acquired, then disposes them once in reverse order', async () => {
    const order = [];
    const listener = vi.fn(() => order.push('event'));
    const first = { dispose: vi.fn(() => order.push('dispose:first')) };
    const second = vi.fn(() => order.push('dispose:second'));
    const view = fixture();

    const start = view.controller.start(async ({ own, listen }) => {
      order.push('setup');
      expect(own(first)).toBe(first);
      expect(own(second)).toBe(second);
      listen(window, 'test-lifecycle', listener);
      order.push('startup');
    });
    await expect(start).resolves.toEqual({ status: 'started' });
    await expect(view.controller.start()).resolves.toEqual({ status: 'started' });
    window.dispatchEvent(new Event('test-lifecycle'));
    expect(order).toEqual(['setup', 'startup', 'event']);
    expect(view.controller.isStarted()).toBe(true);

    await view.controller.dispose();
    await view.controller.dispose();
    window.dispatchEvent(new Event('test-lifecycle'));
    expect(order).toEqual([
      'setup', 'startup', 'event', 'dispose:second', 'dispose:first',
    ]);
    expect(first.dispose).toHaveBeenCalledOnce();
    expect(second).toHaveBeenCalledOnce();
    expect(listener).toHaveBeenCalledOnce();
    expect(view.controller.isDisposed()).toBe(true);
  });

  it('cleans resources acquired before setup fails', async () => {
    const cleanup = vi.fn();
    const view = fixture();

    await expect(view.controller.start(({ own }) => {
      own(cleanup);
      throw new Error('setup failed');
    })).rejects.toThrow('setup failed');
    expect(cleanup).toHaveBeenCalledOnce();
    expect(view.controller.isDisposed()).toBe(true);
  });

  it('continues teardown after a cleanup failure', async () => {
    const order = [];
    const view = fixture();
    await view.controller.start(({ own }) => {
      own(() => order.push('first'));
      own(() => { throw new Error('cleanup failed'); });
      own(() => order.push('last'));
    });

    await expect(view.controller.dispose()).resolves.toMatchObject({
      status: 'disposed',
      cleanupErrors: [expect.objectContaining({ message: 'cleanup failed' })],
    });
    expect(order).toEqual(['last', 'first']);
    expect(view.diagnostics).toHaveBeenCalledWith(
      'Application cleanup failed',
      expect.objectContaining({ message: 'cleanup failed' }),
    );
  });

  it('keeps dirty sessions alive after beforeunload and tears down on pagehide', async () => {
    const cleanup = vi.fn();
    const listener = vi.fn();
    const view = fixture({ isDirty: () => true });
    await view.controller.start(({ own, listen }) => {
      own(cleanup);
      listen(window, 'test-lifecycle-dirty', listener);
    });

    const event = new Event('beforeunload', { cancelable: true });
    window.dispatchEvent(event);
    await Promise.resolve();
    expect(event.defaultPrevented).toBe(true);
    expect(cleanup).not.toHaveBeenCalled();
    window.dispatchEvent(new Event('test-lifecycle-dirty'));
    expect(listener).toHaveBeenCalledOnce();
    expect(view.controller.isDisposed()).toBe(false);

    window.dispatchEvent(new Event('pagehide'));
    expect(view.controller.isDisposed()).toBe(true);
    await view.controller.dispose();
    expect(cleanup).toHaveBeenCalledOnce();
    window.dispatchEvent(new Event('test-lifecycle-dirty'));
    expect(listener).toHaveBeenCalledOnce();
  });
})

