      '| --- | --- |',
      '| 1 | 2 |',
      '```js',
      'const ready = true;',
      '```',
    ];
    expect(classicLineKinds(lines)).toEqual([
      'heading1',
      'paragraph',
      'paragraph',
      'bullet',
      'image',
      'table',
      'table',
      'table',
      'fence',
      'code',
      'fence',
    ]);
