    const MIN_ZOOM = 0.5;
    const MAX_ZOOM = 3.0;
    const STEP = 0.1;

    it('increases zoom when deltaY is negative (scrolling up)', () => {
      expect(calculateNewZoom(1.0, -100, STEP, MIN_ZOOM, MAX_ZOOM)).toBeCloseTo(1.1);
    });

    it('decreases zoom when deltaY is positive (scrolling down)', () => {
