    });

    it('does not exceed MAX_ZOOM limit', () => {
      expect(calculateNewZoom(3.0, -100, STEP, MIN_ZOOM, MAX_ZOOM)).toBe(3.0);
    });

    it('does not go below MIN_ZOOM limit', () => {
