describe('reading tools', () => {
    it('finds Markdown delimiters without changing source content', () => {
      const tokens = (line) => getMarkdownSourceTokenRanges(line)
        .map(({ start, end }) => line.slice(start, end));

      expect(tokens('# open.md')).toEqual(['#']);
      expect(tokens('- **bold** and `code`')).toEqual(['-', '**', '**', '`', '`']);
      expect(tokens('> Quote')).toEqual(['>']);
      expect(tokens('[Docs](guide.md)')).toEqual(['[', '](', ')']);
      expect(tokens('plain a_b identifier')).toEqual([]);
    });

    it('normalizes structured payloads and rejects the removed string contract', () => {
      expect(normalizeDocumentPayload({
        html: '<h1>Title</h1>',
        source: '# Title\n',
        lineCount: 2,
        characterCount: 8,
        wordCount: 2,
        readingTimeMinutes: 1,
      })).toEqual({
        html: '<h1>Title</h1>',
        source: '# Title\n',
        lineCount: 2,
        characterCount: 8,
        wordCount: 2,
        readingTimeMinutes: 1,
      });
      expect(() => normalizeDocumentPayload('<p>Legacy</p>')).toThrow('Invalid document payload');
      expect(normalizeDocumentPayload({
        html: '<pre>art</pre>',
        source: 'art',
        format: 'nfo',
        kind: 'text',
        sourceEncoding: 'cp437',
        lineCount: 1,
        characterCount: 3,
        wordCount: 1,
        readingTimeMinutes: 1,
      })).toMatchObject({ format: 'nfo', kind: 'text', sourceEncoding: 'cp437' });
      expect(normalizeDocumentPayload({
        html: '<pre>ready</pre>',
        source: 'ready',
        format: 'log',
        kind: 'text',
        lineCount: 1,
        characterCount: 5,
        wordCount: 1,
        readingTimeMinutes: 1,
      })).toMatchObject({ format: 'log', kind: 'text' });
    });

    it('keeps essential document counts and only exposes a custom zoom', () => {
      const defaultZoom = getDocumentStatusMetrics({
        lineCount: 42,
        characterCount: 1280,
        zoomPercent: 100,
        currentLine: 9,
        showCurrentLine: true,
        readingProgress: 25,
        readingTimeMinutes: 8,
        showReadingStats: true,
      });

      expect(defaultZoom.visible).toEqual(['42 lines', '1,280 chars', 'Ln 9', '25%', '6 min left']);
      expect(defaultZoom.accessible).toEqual([
        '42 lines',
        '1,280 characters',
        'Line 9',
        '25 percent through document',
        '6 minutes left',
      ]);
      expect(defaultZoom.items.some(({ kind }) => kind === 'zoom')).toBe(false);

      const customZoom = getDocumentStatusMetrics({
        lineCount: 1,
        characterCount: 8,
        zoomPercent: 125,
        currentLine: 3,
        showCurrentLine: true,
        showReadingStats: false,
      });
      expect(customZoom.visible).toEqual(['1 line', '8 chars', 'Ln 3', '125%']);
      expect(customZoom.items).toContainEqual({
        kind: 'zoom',
        visible: '125%',
        accessible: 'Zoom 125 percent',
      });
    });

    it('uses the correct accessible maximize and restore presentation', () => {
      expect(getWindowControlPresentation(false)).toEqual({
        label: 'Maximize',
        iconClass: 'iconoir-square',
      });
      expect(getWindowControlPresentation(true)).toEqual({
        label: 'Restore',
        iconClass: 'iconoir-multi-window',
      });
    });

    it('accepts explicit booleans and fills missing tool defaults', () => {
      expect(normalizeReadingTools({
        lineGuide: true,
        minimap: 'true',
        source: false,
        stats: 1,
        wordWrap: false,
      })).toEqual({
        lineGuide: true,
        minimap: false,
        source: false,
        stats: false,
        wordWrap: false,
        coloredHeadings: false,
      });
      expect(normalizeReadingTools({})).toEqual({
        lineGuide: false,
        minimap: false,
        source: false,
        stats: false,
        wordWrap: true,
        coloredHeadings: false,
      });
      expect(normalizeReadingTools({ blockEditor: true }).blockEditor).toBeUndefined();
    });

